// Junta todos os telefones do pool num array unico para checar o WhatsApp de uma vez
const rows = $input.all().map(i => i.json);
const numeros = [...new Set(rows.map(r => String(r.telefone)))];
return [{ json: { numeros, rows } }];

const items = $input.all().map(i => i.json);
let lista = [];
if (items.length === 1) {
  const j = items[0];
  lista = Array.isArray(j) ? j : (j.data || j.result || [j]);
} else {
  lista = items.flatMap(j => Array.isArray(j) ? j : (j.data || j.result || [j]));
}

const digits = s => String(s || '').replace(/\D/g, '');

// gera as variantes com e sem o 9 (problema clássico BR)
function variantes(num) {
  const d = digits(num);
  const set = new Set([d]);
  if (d.length === 13 && d.substr(4, 1) === '9') set.add(d.substr(0, 4) + d.substr(5)); // tira o 9
  else if (d.length === 12) set.add(d.substr(0, 4) + '9' + d.substr(4));                // põe o 9
  return [...set];
}

// mapa de quem tem WhatsApp, indexado por TODAS as variantes
const existe = {};
for (const it of lista) {
  const num = digits(it && (it.number || it.jid));
  if (num && it.exists === true) for (const v of variantes(num)) existe[v] = true;
}

const rows = $('Monta lista de números1').first().json.rows;

// mantém só quem tem WhatsApp (comparando variantes)
const comWhats = rows.filter(r => variantes(r.telefone).some(v => existe[v] === true));

// 1 disparo por pessoa/dia: mantém a linha de maior score
const porTelefone = {};
for (const r of comWhats) {
  const k = digits(r.telefone);
  if (!porTelefone[k] || Number(r.score) > Number(porTelefone[k].score)) porTelefone[k] = r;
}

return Object.values(porTelefone).slice(0, 30).map(r => ({ json: r }));

const item = $('Loop Interessados').item.json;

// ---- Valor ----
function fmtNum(n){
  const [int, dec] = Number(n).toFixed(2).split('.');
  return int.replace(/\B(?=(\d{3})+(?!\d))/g,'.') + ',' + dec;
}
const precoNum = Number(item.anuncio_price);
const temValor = !!precoNum && precoNum > 0;
const simbolo  = { 1: 'R$', 2: 'US$', 3: '€' }[item.moeda_id] || 'R$';
const unidade  = item.price_unit_nome ? '/' + item.price_unit_nome : '';
const valorFmt = temValor ? `${simbolo} ${fmtNum(precoNum)}${unidade}` : null;

// ---- Região ----
const cidade = (item.anuncio_cidade || '').trim();
const uf     = (item.anuncio_uf || '').trim();
let regiaoFmt = null;
if (cidade && uf) regiaoFmt = `${cidade}/${uf}`;
else if (uf)      regiaoFmt = uf;
else if (cidade)  regiaoFmt = cidade;
const temRegiao = !!regiaoFmt;

const produto = String(item.produto_nome || 'seu produto');

// ---- Escolha do template + texto final (o que realmente será enviado) ----
// IMPORTANTE: os textos abaixo devem ser IDÊNTICOS ao corpo aprovado de cada
// template no Meta. Ajuste as strings se a redação do seu template for diferente.
const saudacao = 'Olá, tudo bem? 😊\n\nSou a Luana, da AgroNegociar.\n\n';
const fim = '\n\nQuer que eu te mande o link?';

let templateName, params, textoLog;
if (temValor && temRegiao) {
  templateName = 'template_1_agronegociar';   // Template 1: preço + local
  params = [produto, valorFmt, regiaoFmt];
  textoLog = `${saudacao}Vi aqui no seu cadastro que você possui interesse em ${produto} e acabou de surgir um anúncio no valor de ${valorFmt} na região de ${regiaoFmt}.${fim}`;
} else if (temValor) {
  templateName = 'template_2_agronegociar';   // Template 2: só preço
  params = [produto, valorFmt];
  textoLog = `${saudacao}Vi aqui no seu cadastro que você possui interesse em ${produto} e acabou de surgir um anúncio de ${produto} no valor de ${valorFmt}.${fim}`;
} else {
  templateName = 'template_4_agronegociar';   // Template sem valor
  params = [produto];
  textoLog = `${saudacao}Vi aqui no seu cadastro que você possui interesse em ${produto} e acabou de surgir um anúncio de ${produto}.${fim}`;
}

const body = {
  messaging_product: 'whatsapp',
  to: String(item.telefone),
  type: 'template',
  template: {
    name: templateName,
    language: { code: 'pt_BR' },
    components: [
      { type: 'body', parameters: params.map(t => ({ type: 'text', text: String(t) })) }
    ]
  }
};

return [{
  json: {
    resultado: body,
    telefone: item.telefone,
    whatsapp_number_id: '1123205217553260',
    anuncio_id: item.anuncio_id,
    candidato_id: item.candidato_id,
    score: item.score,
    template_usado: templateName,
    texto_log: textoLog
  }
}];

// Monta a reabordagem + o payload de template do Meta (WhatsApp Cloud API)
// SEM usar o nome do lead (costuma vir bagunçado).
const it = $json;
const produto = (it.produto || '').trim();
const alvo = produto || 'os anúncios';

// Texto igual ao body do template aprovado no Meta:
const texto = `Oi! Tudo bem? Lembrei de você! Você tinha pedido para eu te chamar para falarmos sobre ${alvo}. Chegaram umas novidades perfeitas sobre isso. Tem um tempinho agora?`;

// Template "template_retorno_agronegociar" (pt_BR), 1 variável: {{1}} = produto.
const resultado = {
  messaging_product: "whatsapp",
  to: it.telefone,
  type: "template",
  template: {
    name: "template_retorno_agronegociar",
    language: { code: "pt_BR" },
    components: [
      { type: "body", parameters: [ { type: "text", text: alvo } ] }
    ]
  }
};

return [{ json: { ...it, texto_log: texto, resultado } }];

